scwin.vScrenID = "ULDINS31000.xml";
scwin.cnt_day = 0;
scwin.cnt_time = 0;
scwin.cnt_month = 0;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명   : ins_search_day
 * 설명       : 통계  목록 조회한다.
 ***********************************************/
scwin.ins_search_day = function() {
    if ($c.stf.getObjectValue(edt_pSTD_CD_GRNT_DD_SDATE).length != 8) {
        $c.win.alert("조회 시작일 날자을 8자리(예:2012-10-10) 입력하십시요");
        return false;
    }
    if ($c.stf.getObjectValue(edt_pSTD_CD_GRNT_DD_EDATE).length != 8) {
        $c.win.alert("조회 마지막 날자를 8자리(예:2013-10-10) 입력하십시요");
        return false;
    }

    // 검색일 체크
    if ($c.stf.compareFromToDate2(edt_pSTD_CD_GRNT_DD_SDATE, edt_pSTD_CD_GRNT_DD_EDATE) == false) {
        return false;
    }
    tab_IsurInfo.setSelectedTabIndex("1");

    //데이터셋 초기화
    dts_StdCdDayList.removeAll();
    dts_IsuInstDayList.removeAll();
    dts_BndDayList.removeAll();
    $c.cm.ShowWin(panel_3); // 그리드명을 표기

    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamicName" + "&outputMessageId=ULDINS31000_STDCD_LIST_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.stdcd.select.listStdCdStatsDayListInquiry" + "&{P}STD_CD_GRNT_DD_SDATE=" + edt_pSTD_CD_GRNT_DD_SDATE.getValue() + "&{P}STD_CD_GRNT_DD_EDATE=" + edt_pSTD_CD_GRNT_DD_EDATE.getValue();
    dts_StdCdDayList.DataID = encodeURI(url);
    dts_StdCdDayList.reset();
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamicName" + "&outputMessageId=ULDINS31000_ISUINST_LIST_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.stdcd.select.listIsuInstStatsDayListInquiry" + "&{P}STD_CD_GRNT_DD_SDATE=" + edt_pSTD_CD_GRNT_DD_SDATE.getValue() + "&{P}STD_CD_GRNT_DD_EDATE=" + edt_pSTD_CD_GRNT_DD_EDATE.getValue();
    dts_IsuInstDayList.DataID = encodeURI(url);
    dts_IsuInstDayList.reset();
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamicName" + "&outputMessageId=ULDINS31000_BND_LIST_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.stdcd.select.listBndStatsDayListInquiry" + "&{P}STD_CD_GRNT_DD_SDATE=" + edt_pSTD_CD_GRNT_DD_SDATE.getValue() + "&{P}STD_CD_GRNT_DD_EDATE=" + edt_pSTD_CD_GRNT_DD_EDATE.getValue();
    dts_BndDayList.DataID = encodeURI(url);
    dts_BndDayList.reset();
};



/********************************************** 
 * 함수명   : ins_search_time
 * 설명       : 통계  목록 조회한다.
 ***********************************************/
scwin.ins_search_time = function() {
    if ($c.stf.getObjectValue(edt_pSTD_CD_GRNT_DD_DATE).length != 8) {
        $c.win.alert("표준코드부여일 날짜를 8자리(예:2013-10-10) 입력하십시요");
        return false;
    }
    tab_IsurInfo.setSelectedTabIndex("2");

    //데이터셋 초기화
    dts_StdCdTimeList.removeAll();
    dts_BndTimeList.removeAll();
    $c.cm.ShowWin(panel_3); // 그리드명을 표기

    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamicName" + "&outputMessageId=ULDINS31000_STDCD_LIST_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.stdcd.select.listStdCdStatsTimeListInquiry" + "&{P}STD_CD_GRNT_DD_DATE=" + edt_pSTD_CD_GRNT_DD_DATE.getValue() + "&{P}LIST_STAT_CD=" + $c.stf.getObjectValue(cmb_pLIST_STAT_CD);
    dts_StdCdTimeList.DataID = encodeURI(url);
    dts_StdCdTimeList.reset();
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamicName" + "&outputMessageId=ULDINS31000_BND_LIST_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.stdcd.select.listBndStatsTimeListInquiry" + "&{P}STD_CD_GRNT_DD_DATE=" + edt_pSTD_CD_GRNT_DD_DATE.getValue() + "&{P}LIST_STAT_CD=" + $c.stf.getObjectValue(cmb_pLIST_STAT_CD);
    dts_BndTimeList.DataID = encodeURI(url);
    dts_BndTimeList.reset();
};



/********************************************** 
 * 함수명   : ins_search_month
 * 설명       : 월별코드현황 조회한다.
 ***********************************************/
scwin.ins_search_month = function() {
    if ($c.stf.getObjectValue(edt_pSEARCH_YYYY).length != 4) {
        $c.win.alert("검색년도를 4자리(예:2014) 입력하십시요");
        return false;
    }
    tab_IsurInfo.setSelectedTabIndex("3");

    //데이터셋 초기화
    dts_StdByddStat.removeAll();
    $c.cm.ShowWin(panel_2); // 그리드명을 표기

    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamicName" + "&outputMessageId=ULDINS31000_STD_BYDD_STAT_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.stdcd.select.listStdByddStat" + "&{P}V_ACTIV_TP_CD=" + $c.stf.getObjectValue(cmb_pACTIV_TP_CD);

    //선택 년도의 각월말일을 가져와서 파라메터로 던진다. 1~12월
    for (var i = 1; i < 13; i++) {
        url += "&{P}V_YYYYMMDD" + i + "=" + dts_MM_END_DATE.getCellData(i, "END_DATE"); //형식:"&{P}V_YYYYMMDD1=20140131"

    }
    dts_StdByddStat.DataID = encodeURI(url);
    dts_StdByddStat.reset();
};



/********************************************** 
 * 함수명   : edt_pSEARCH_YYYY_OnKeyUp
 * 설명       : 검색년도 입력시 해당년도의 월말일을 가져온다
 ***********************************************/
scwin.edt_pSEARCH_YYYY_OnKeyUp = function() {
    if ($c.stf.getObjectValue(edt_pSEARCH_YYYY).length == 4) {
        //데이터셋 초기화
        dts_MM_END_DATE.removeAll();
        var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamicName" + "&outputMessageId=ULDINS31000_MM_END_DATE_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.stdcd.select.listMmEndDate" + "&{P}V_YYYY=" + $c.stf.getObjectValue(edt_pSEARCH_YYYY);
        dts_MM_END_DATE.DataID = encodeURI(url);
        dts_MM_END_DATE.reset();
    }
};
