        file_dts_List.setCellData(add_num, "6", "외국채");
        file_dts_List.setCellData(add_num, "7", "합계");
        file_dts_List.setCellData(add_num, "8", "비중");
        for (var i = 1; i < 5; i++) {
            file_dts_List.insertRow(i + add_num - 1);
            file_dts_List.setCellData(i + add_num, "1", dts_BndTimeList.getCellData(i, "LEFT_TITLE"));
            file_dts_List.setCellData(i + add_num, "2", fn_SetComma(dts_BndTimeList.getCellData(i, "T_01")));
            file_dts_List.setCellData(i + add_num, "3", fn_SetComma(dts_BndTimeList.getCellData(i, "T_02")));
            file_dts_List.setCellData(i + add_num, "4", fn_SetComma(dts_BndTimeList.getCellData(i, "T_03")));
            file_dts_List.setCellData(i + add_num, "5", fn_SetComma(dts_BndTimeList.getCellData(i, "T_04")));
            file_dts_List.setCellData(i + add_num, "6", fn_SetComma(dts_BndTimeList.getCellData(i, "T_05")));
            file_dts_List.setCellData(i + add_num, "7", fn_SetComma(dts_BndTimeList.getCellData(i, "T_SUM")));
            file_dts_List.setCellData(i + add_num, "8", fn_SetComma(dts_BndTimeList.getCellData(i, "T_PART")));
        }
        file_dts_List.insertRow(16);
        file_dts_List.setCellData(17, "1", " * 조회기간내에 [표준코드부여 & 상장폐지] 된 종목도 상장통계에 포함");
        var toDay = $c.ut.cGetToday("yyyymmdd");
        $c.data.downloadGridViewExcel(file_Grid, toDay + "_표준코드통계.xls", "", "8");
    } else if (gubun == "month") {
        var toDay = $c.ut.cGetToday("yyyymmdd");
        $c.data.downloadGridViewExcel(MxGrid_5, toDay + "_표준코드통계.xls", "", "8");
    }
};
scwin.gform_onload = function() {
    $c.libRoundPanel.PanelToGroupBox(panel_1);
    fn_CtrlBtn("no_data");
    ins_combo_set(dts_LIST_STAT_CD, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "00714", "ALL"); //00714 -LIST_STAT_CD

    $c.stf.fn_setFromToDate(5, edt_pSTD_CD_GRNT_DD_SDATE, edt_pSTD_CD_GRNT_DD_EDATE);
    $c.stf.setObjectValue(edt_pSTD_CD_GRNT_DD_DATE, $c.ut.cGetToday("yyyymmdd"));
    $c.stf.setObjectValue(edt_pSEARCH_YYYY, $c.ut.cGetToday("yyyymmdd").substring(0, 4));

    /*
    날짜검색 부분 디자인이 겹쳐 있어서 작업시 위에꺼 내리고 작업해야 함. 
    */
    $c.stf.showObj(label_27, false);
    $c.stf.showObj(edt_pSTD_CD_GRNT_DD_DATE, false);
    $c.stf.showObj(img_pSTD_CD_GRNT_DD_DATE, false);
    $c.stf.showObj(cmb_pLIST_STAT_CD, false);
    $c.stf.showObj(label_9, false);
    $c.stf.showObj(edt_pSEARCH_YYYY, false);
    $c.stf.showObj(label_12, false);
    $c.stf.showObj(cmb_pACTIV_TP_CD, false);

    //활성구분 콤보설정
    $c.stf.setObjectValue(cmb_pACTIV_TP_CD, "");

    //검색년도 OnKeyUp
    scwin.edt_pSEARCH_YYYY_OnKeyUp();
};
scwin.btn_search_onclick = function() {
